/// <summary>Converts a Plane to a 4x4 matrix (columns: xAxis, yAxis, zAxis=cross, origin).</summary>
pub fn plane_to_matrix4(p: &Plane) -> Matrix4<f64> {
    let x = p.x_axis.to_nalgebra();
    let y = p.y_axis.to_nalgebra();
    let mut z = x.cross(&y);
