        x.z, y.z, z.z, p.origin.z,
        0.0, 0.0, 0.0, 1.0,
    )
}

/// <summary>Returns gap/shift/rise unit direction vectors from a parent connector direction.</summary>
pub fn connection_placement_translation_basis(
    parent_connector: &Connector,
) -> (nalgebra::Vector3<f64>, nalgebra::Vector3<f64>, nalgebra::Vector3<f64>) {
    use nalgebra::{UnitQuaternion, Vector3};
    let mut parent_dir = Vector3::new(
        parent_connector.direction.x,
        parent_connector.direction.y,
        parent_connector.direction.z,
    );
