// Jacobian-based move helpers MUST compute connection diffs via numerical Jacobian of compute_child_plane_matrix.

/// <summary>Converts a Plane to a 4x4 matrix (columns: xAxis, yAxis, zAxis=cross, origin).</summary>
pub fn plane_to_matrix4(p: &Plane) -> Matrix4<f64> {
    let x = p.x_axis.to_nalgebra();
    let y = p.y_axis.to_nalgebra();
    let mut z = x.cross(&y);
    if z.norm() > 1e-12 {
        z.normalize_mut();
    }
    Matrix4::new(
        x.x, y.x, z.x, p.origin.x,
        x.y, y.y, z.y, p.origin.y,
        x.z, y.z, z.z, p.origin.z,
        0.0, 0.0, 0.0, 1.0,
    )
}

/// <summary>Returns gap/shift/rise unit direction vectors from a parent connector direction.</summary>
pub fn connection_placement_translation_basis(
    parent_connector: &Connector,
) -> (nalgebra::Vector3<f64>, nalgebra::Vector3<f64>, nalgebra::Vector3<f64>) {
    use nalgebra::{UnitQuaternion, Vector3};
    let mut parent_dir = Vector3::new(
        parent_connector.direction.x,
        parent_connector.direction.y,
        parent_connector.direction.z,
    );
    if parent_dir.norm() > 1e-12 {
        parent_dir.normalize_mut();
    }
    let y_axis = Vector3::new(0.0, 1.0, 0.0);
    let dot_val = y_axis.dot(&parent_dir);
    let parent_connector_quat = if (dot_val + 1.0).abs() < 0.0001 {
        UnitQuaternion::from_axis_angle(&Vector3::z_axis(), PI)
    } else {
        UnitQuaternion::rotation_between(&y_axis, &parent_dir)
            .unwrap_or_else(UnitQuaternion::identity)
    };
    let parent_rotation_t = quat_to_matrix4(&parent_connector_quat);
    let mut gap_dir = apply_matrix4_to_vec3(&parent_rotation_t, &Vector3::new(0.0, 1.0, 0.0));
    let mut shift_dir = apply_matrix4_to_vec3(&parent_rotation_t, &Vector3::new(1.0, 0.0, 0.0));
    let mut raise_dir = apply_matrix4_to_vec3(&parent_rotation_t, &Vector3::new(0.0, 0.0, 1.0));
    if gap_dir.norm() > 1e-12 { gap_dir.normalize_mut(); }
    if shift_dir.norm() > 1e-12 { shift_dir.normalize_mut(); }
    if raise_dir.norm() > 1e-12 { raise_dir.normalize_mut(); }
    (gap_dir, shift_dir, raise_dir)
}

/// <summary>Computes child connector origin in world space given parent plane, connectors and connection.</summary>
pub fn child_connector_origin_world(
    parent_plane: &Plane,
    parent_connector: &Connector,
    child_connector: &Connector,
    connection: &Connection,
) -> nalgebra::Vector3<f64> {
    let parent_matrix = plane_to_matrix4(parent_plane);
    let local_transform = compute_child_plane_matrix(parent_connector, child_connector, connection);
    let final_matrix = parent_matrix * local_transform;
    nalgebra::Vector3::new(final_matrix[(0, 3)], final_matrix[(1, 3)], final_matrix[(2, 3)])
}

/// <summary>Returns a copy of connection with a numeric field perturbed by delta.</summary>
pub fn connection_with_numeric_delta(connection: &Connection, key: &str, delta: f64) -> Connection {
    let mut c = connection.clone();
    match key {
        "gap" => c.gap += delta,
        "shift" => c.shift += delta,
        "rise" => c.rise += delta,
        "rotation" => c.rotation += delta,
        "turn" => c.turn += delta,
        "tilt" => c.tilt += delta,
        _ => {}
    }
    c
}

/// <summary>Solves min-norm: find deltas such that J*deltas ≈ t, using (JJ^T)^{-1}.</summary>
pub fn solve_connection_origin_min_norm(
    cols: &[nalgebra::Vector3<f64>],
    t: &nalgebra::Vector3<f64>,
) -> Option<Vec<f64>> {
    if cols.is_empty() {
        return None;
    }
    // Build 3x3 JJ^T (column-major storage: jjt[r + c*3])
    let mut jjt = [0.0f64; 9];
    for c in 0..3 {
        for r in 0..3 {
            let mut s = 0.0;
            for col in cols {
                s += col[r] * col[c];
            }
            jjt[r + c * 3] = s;
        }
    }
    // Regularization
    jjt[0] += 1e-14;
    jjt[4] += 1e-14;
    jjt[8] += 1e-14;
    // Determinant
    let det = jjt[0] * (jjt[4] * jjt[8] - jjt[7] * jjt[5])
        - jjt[3] * (jjt[1] * jjt[8] - jjt[7] * jjt[2])
        + jjt[6] * (jjt[1] * jjt[5] - jjt[4] * jjt[2]);
    if det.abs() < 1e-22 {
        return None;
    }
    let inv_det = 1.0 / det;
    let mut inv = [0.0f64; 9];
    inv[0] = (jjt[4] * jjt[8] - jjt[5] * jjt[7]) * inv_det;
    inv[1] = (jjt[2] * jjt[7] - jjt[1] * jjt[8]) * inv_det;
    inv[2] = (jjt[1] * jjt[5] - jjt[2] * jjt[4]) * inv_det;
    inv[3] = (jjt[5] * jjt[6] - jjt[3] * jjt[8]) * inv_det;
    inv[4] = (jjt[0] * jjt[8] - jjt[2] * jjt[6]) * inv_det;
    inv[5] = (jjt[2] * jjt[3] - jjt[0] * jjt[5]) * inv_det;
    inv[6] = (jjt[3] * jjt[7] - jjt[4] * jjt[6]) * inv_det;
    inv[7] = (jjt[1] * jjt[6] - jjt[0] * jjt[7]) * inv_det;
    inv[8] = (jjt[0] * jjt[4] - jjt[1] * jjt[3]) * inv_det;
    if inv[0].is_infinite() || inv[0].is_nan() {
        return None;
    }
    // u = inv * t (column-major)
    let u = nalgebra::Vector3::new(
        inv[0] * t[0] + inv[3] * t[1] + inv[6] * t[2],
        inv[1] * t[0] + inv[4] * t[1] + inv[7] * t[2],
        inv[2] * t[0] + inv[5] * t[1] + inv[8] * t[2],
    );
    // deltas[i] = cols[i] · u
    let deltas: Vec<f64> = cols.iter().map(|col| col.dot(&u)).collect();
    Some(deltas)
}

/// <summary>Fallback: projects translation onto connector basis + parent plane u/v.</summary>
pub fn connection_diff_translation_fallback(
    parent_plane: &Plane,
    parent_connector: &Connector,
    tw: &nalgebra::Vector3<f64>,
) -> ConnectionDiff {
    let (gap_dir, shift_dir, raise_dir) = connection_placement_translation_basis(parent_connector);
    let dgap = tw.dot(&gap_dir);
    let dshift = tw.dot(&shift_dir);
    let drise = tw.dot(&raise_dir);
    let res = *tw - dgap * gap_dir - dshift * shift_dir - drise * raise_dir;
    let px = parent_plane.x_axis.to_nalgebra();
    let py = parent_plane.y_axis.to_nalgebra();
    let eps = 1e-9;
    let mut diff = ConnectionDiff {
        guid: String::new(),
        ..Default::default()
    };
    if dgap.abs() > eps {
        diff.gap = Some(dgap);
    }
    if dshift.abs() > eps {
        diff.shift = Some(dshift);
    }
    if drise.abs() > eps {
        diff.rise = Some(drise);
    }
    let px_sq = px.norm_squared();
    let py_sq = py.norm_squared();
    if px_sq > 1e-24 && py_sq > 1e-24 {
        let px_n = px / px_sq.sqrt();
        let py_n = py / py_sq.sqrt();
        let du = res.dot(&px_n);
        let dv = res.dot(&py_n);
        if du.abs() > eps {
            diff.u = Some(Some(du));
        }
        if dv.abs() > eps {
            diff.v = Some(Some(dv));
        }
    }
    diff
}

/// <summary>Builds 6-column Jacobian and solves min-norm for connection diffs from a structural move vector.</summary>
pub fn connection_diff_from_structural_move_vector(
    parent_plane: &Plane,
    parent_connector: &Connector,
    child_connector: Option<&Connector>,
    connection: &Connection,
    child_plane: Option<&Plane>,
    vector: &MoveVector,
) -> ConnectionDiff {
    let child = child_plane.cloned().unwrap_or_default();
    let tw_vec = move_translation_world_from_piece_plane(&child, vector);
    let tw = nalgebra::Vector3::new(tw_vec.x, tw_vec.y, tw_vec.z);
    if tw.norm_squared() < 1e-24 {
        return ConnectionDiff {
            guid: String::new(),
            ..Default::default()
        };
    }
    let child_conn = match child_connector {
        Some(c) => c,
        None => {
            return connection_diff_translation_fallback(parent_plane, parent_connector, &tw);
        }
    };
    let jacobian_keys = ["gap", "shift", "rise", "rotation", "turn", "tilt"];
    let jacobian_eps = |key: &str| -> f64 {
        match key {
            "gap" | "shift" | "rise" => 1e-6,
            _ => 1e-4,
        }
    };
    let o0 = child_connector_origin_world(parent_plane, parent_connector, child_conn, connection);
    let cols: Vec<nalgebra::Vector3<f64>> = jacobian_keys
        .iter()
        .map(|&key| {
            let eps = jacobian_eps(key);
            let perturbed = connection_with_numeric_delta(connection, key, eps);
            let o1 = child_connector_origin_world(parent_plane, parent_connector, child_conn, &perturbed);
            (o1 - o0) / eps
        })
        .collect();
    let deltas = solve_connection_origin_min_norm(&cols, &tw);
    let eps_out = 1e-9;
    match deltas {
        Some(deltas) => {
            let mut diff = ConnectionDiff {
                guid: String::new(),
                ..Default::default()
            };
            for (i, &key) in jacobian_keys.iter().enumerate() {
                if deltas[i].abs() > eps_out {
                    let v = deltas[i];
                    match key {
                        "gap" => diff.gap = Some(v),
                        "shift" => diff.shift = Some(v),
                        "rise" => diff.rise = Some(v),
                        "rotation" => diff.rotation = Some(v),
                        "turn" => diff.turn = Some(v),
                        "tilt" => diff.tilt = Some(v),
                        _ => {}
                    }
                }
            }
            // Compute residual
            let mut pred = nalgebra::Vector3::zeros();
            for (i, col) in cols.iter().enumerate() {
                pred += col * deltas[i];
            }
            let res = tw - pred;
            let px = parent_plane.x_axis.to_nalgebra();
            let py = parent_plane.y_axis.to_nalgebra();
            let px_sq = px.norm_squared();
            let py_sq = py.norm_squared();
            if px_sq > 1e-24 && py_sq > 1e-24 {
                let px_n = px / px_sq.sqrt();
                let py_n = py / py_sq.sqrt();
                let du = res.dot(&px_n);
                let dv = res.dot(&py_n);
                if du.abs() > eps_out {
                    diff.u = Some(Some(du));
                }
                if dv.abs() > eps_out {
                    diff.v = Some(Some(dv));
                }
            }
            diff
        }
        None => connection_diff_translation_fallback(parent_plane, parent_connector, &tw),
    }
}
//#endregion

/// <summary>Computes a DesignDiff that translates root piece planes and adjusts connection diffs using a numerical Jacobian for selected child movers.</summary>
/// <remarks>
/// </remarks>
pub fn move_pieces_in_design(
    kit: &Kit,
    design_pieces: &[Piece],
    design_connections: &[Connection],
    selected_pieces: &[Piece],
    vector: &MoveVector,
) -> DesignDiff {
    let types_dict: HashMap<&str, &Type> = kit
        .types
        .as_ref()
        .map(|types| types.iter().map(|t| (t.guid.as_str(), t)).collect())
        .unwrap_or_default();
    let selected_guids: HashSet<&str> =
        selected_pieces.iter().map(|p| p.guid.as_str()).collect();
    let mut parent_map: HashMap<&str, (&str, &str)> = HashMap::new();
    for conn in design_connections {
        let connecting_guid = conn.connecting.piece.guid.as_str();
        let connected_guid = conn.connected.piece.guid.as_str();
        parent_map.insert(connecting_guid, (conn.guid.as_str(), connected_guid));
    }
    let piece_map: HashMap<&str, &Piece> =
        design_pieces.iter().map(|p| (p.guid.as_str(), p)).collect();
    let conn_map: HashMap<&str, &Connection> =
        design_connections.iter().map(|c| (c.guid.as_str(), c)).collect();
    let fixed_guids: HashSet<&str> = selected_guids
        .iter()
        .filter(|&&guid| !parent_map.contains_key(guid))
        .copied()
        .collect();
    let piece_updates: Vec<DiffUpdate<PieceDiff>> = fixed_guids
        .iter()
        .filter_map(|&guid| {
            let piece = piece_map.get(guid)?;
            let base = piece.plane.as_ref()?;
            let t = move_translation_world_from_piece_plane(base, vector);
            let new_plane = Plane {
                origin: Vector::new(
                    base.origin.x + t.x,
                    base.origin.y + t.y,
                    base.origin.z + t.z,
                ),
                x_axis: base.x_axis.clone(),
                y_axis: base.y_axis.clone(),
            };
            Some(DiffUpdate {
                key: "piece".to_string(),
                guid: guid.to_string(),
                diff: PieceDiff {
                    guid: guid.to_string(),
                    plane: Some(Some(new_plane)),
                    ..Default::default()
                },
            })
        })
        .collect();
    let connection_updates: Vec<DiffUpdate<ConnectionDiff>> = selected_guids
        .iter()
        .filter(|&&guid| {
            if fixed_guids.contains(guid) {
                return false;
            }
            let mut current = guid;
            loop {
                match parent_map.get(current) {
                    Some(&(_conn_guid, ancestor_guid)) => {
                        if selected_guids.contains(ancestor_guid) {
                            return false;
                        }
                        current = ancestor_guid;
                    }
                    None => break,
                }
            }
            parent_map.contains_key(guid)
        })
        .filter_map(|&guid| {
            let (conn_guid, parent_guid) = parent_map[guid];
            let connection = conn_map.get(conn_guid)?;
            let parent_piece = piece_map.get(parent_guid)?;
            let child_piece = piece_map.get(guid)?;
            let parent_type_guid = parent_piece.type_ref.as_ref().map(|t| t.guid.as_str())?;
            let child_type_guid = child_piece.type_ref.as_ref().map(|t| t.guid.as_str())?;
            let parent_type = types_dict.get(parent_type_guid)?;
            let child_type = types_dict.get(child_type_guid)?;
            let parent_connector_guid = connection
                .connected
                .connector
                .as_ref()
                .map(|c| c.guid.as_str());
            let child_connector_guid = connection
                .connecting
                .connector
                .as_ref()
                .map(|c| c.guid.as_str());
            let parent_connector =
                get_connector_from_type(&types_dict, parent_type, parent_connector_guid)?;
            let child_connector =
                get_connector_from_type(&types_dict, child_type, child_connector_guid);
            let parent_plane = parent_piece.plane.as_ref().cloned().unwrap_or_default();
            let conn_diff = connection_diff_from_structural_move_vector(
                &parent_plane,
                parent_connector,
                child_connector,
                connection,
                child_piece.plane.as_ref(),
                vector,
            );
            let has_fields = conn_diff.gap.is_some()
                || conn_diff.shift.is_some()
                || conn_diff.rise.is_some()
                || conn_diff.rotation.is_some()
                || conn_diff.turn.is_some()
                || conn_diff.tilt.is_some()
                || conn_diff.u.is_some()
                || conn_diff.v.is_some();
            if !has_fields {
                return None;
            }
            Some(DiffUpdate {
                key: "connection".to_string(),
                guid: conn_guid.to_string(),
                diff: ConnectionDiff {
                    guid: conn_guid.to_string(),
                    gap: conn_diff.gap,
                    shift: conn_diff.shift,
                    rise: conn_diff.rise,
                    rotation: conn_diff.rotation,
                    turn: conn_diff.turn,
                    tilt: conn_diff.tilt,
                    u: conn_diff.u,
                    v: conn_diff.v,
                    ..Default::default()
                },
            })
        })
        .collect();
    let mut diff = DesignDiff {
        guid: String::new(),
        ..Default::default()
    };
    if !piece_updates.is_empty() {
        diff.pieces = Some(CollectionDiff {
            added: None,
            removed: None,
            updated: Some(piece_updates),
        });
    }
    if !connection_updates.is_empty() {
        diff.connections = Some(CollectionDiff {
            added: None,
            removed: None,
            updated: Some(connection_updates),
        });
    }
    diff
}

