                Diff = connDiff,
            });
        }
        var diff = new DesignDiff();
        if (pieceUpdates.Count > 0)
            diff.Pieces = new PiecesDiff { Updated = pieceUpdates };
        if (connectionUpdates.Count > 0)
            diff.Connections = new ConnectionsDiff { Updated = connectionUpdates };
